#!/usr/bin/env python3
from __future__ import annotations
import argparse,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.tfg_phase0.visual_reranking import canonical_bytes
CLASSES=('supported','contradicted','unverifiable')
def main():
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--annotations',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run=json.loads(a.run.read_text());human=json.loads(a.annotations.read_text());pred={(r['candidate_id'],r['image_id'],r['claim_id']):r for r in run['records']};truth={(r['candidate_id'],r['image_id'],r['claim_id']):r for r in human['records']};assert set(pred)==set(truth) and len(pred)==60;matrix={c:{x:0 for x in CLASSES+('invalid_output',)} for c in CLASSES};rows=[]
 for key,h in truth.items():
  r=pred[key];v=r['verdict'] if r['status'] in {'valid','policy_unverifiable'} else None;matrix[h['human_verdict']][v or 'invalid_output']+=1;explanation=(r.get('explanation') or '').strip().casefold();inconsistent=bool(v in {'supported','contradicted'} and explanation=='no verificable');rows.append({'candidate_id':key[0],'image_id':key[1],'claim_id':key[2],'human':h['human_verdict'],'predicted':v,'correct':v==h['human_verdict'],'status':r['status'],'explanation_status':r['explanation_status'],'explanation':r.get('explanation'),'explanation_inconsistent':inconsistent})
 per={}
 for c in CLASSES:
  tp=matrix[c][c];fp=sum(matrix[t][c] for t in CLASSES if t!=c);fn=sum(matrix[c][x] for x in CLASSES+('invalid_output',) if x!=c);precision=tp/(tp+fp) if tp+fp else None;recall=tp/(tp+fn) if tp+fn else None;f1=2*precision*recall/(precision+recall) if precision is not None and recall is not None and precision+recall else 0.;per[c]={'support':sum(matrix[c].values()),'precision':precision,'recall':recall,'f1':f1}
 valid=sum(r['predicted'] is not None for r in rows);correct=sum(r['correct'] for r in rows);summary={'pairs':60,'valid_decisions':valid,'valid_fraction':valid/60,'accuracy':correct/60,'macro_f1':sum(x['f1'] for x in per.values())/3,'false_supports':sum(matrix[t]['supported'] for t in CLASSES if t!='supported'),'false_contradictions':sum(matrix[t]['contradicted'] for t in CLASSES if t!='contradicted'),'correct_abstentions':matrix['unverifiable']['unverifiable'],'incorrect_abstentions':sum(matrix[t]['unverifiable'] for t in ('supported','contradicted')),'invalid_outputs':60-valid,'explanation_valid':sum(r['explanation_status']=='valid' for r in run['records']),'explanation_inconsistent':sum(r['explanation_inconsistent'] for r in rows),'decision_latency_mean_seconds':sum(r['decision_seconds'] for r in run['records'])/max(1,sum(r['status']=='valid' for r in run['records'])),'explanation_latency_mean_seconds':sum(r['explanation_seconds'] for r in run['records'])/max(1,sum(r['explanation_status']!='not_requested' for r in run['records']))}
 doc={'schema_version':'1.0','contract_version':'visual-verdict-evaluation-v4','inputs':{'run_sha256':hashlib.sha256(a.run.read_bytes()).hexdigest(),'annotations_sha256':hashlib.sha256(a.annotations.read_bytes()).hexdigest()},'summary':summary,'confusion_matrix':{'rows':list(CLASSES),'columns':list(CLASSES)+['invalid_output'],'counts':matrix},'per_class':per,'per_record':rows,'resources':run['resources'],'limitations':['development_set_used_for_contract_design','single_reviewer','only_two_human_contradictions','no_ocr_claims','no_statistical_generalization']};a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_bytes(canonical_bytes(doc)+b'\n');print(json.dumps(summary,sort_keys=True));return 0
